#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Collisions;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.axolotlSuit_VehicleCrush)]
    public class AxolotlSuit_VehicleCrush : VehicleCrushBehaviour
    {
        public AxolotlSuit_VehicleCrush(string nsp, string name) : base(nsp, name)
        {
        }
        public override bool ShouldCollide(EntityCollision collision, int state)
        {
            if (!base.ShouldCollide(collision, state))
                return false;
            var entity = collision.Entity;
            var other = collision.Other;
            if (AxolotlSuit.IsEmpty(entity) && other.Type != EntityTypes.PLANT)
                return false;
            return true;
        }
    }
}
